import utilSrv from "./utils"
export default (function(){
    var messageSrv = {cbNetworkHooks:null}; //定义消息的监听逻辑
    //设置网络监听的hooks
    messageSrv.sNetworkHooks = (callback) => {
        messageSrv.cbNetworkHooks = callback;
    };
    //发送消息的处理业务逻辑
    messageSrv.doSendTaskDispatchMessage = (link, callback)=> {
        const params = {type:utilSrv.msgTypeDispatchTask, link:link};
        chrome.runtime.sendMessage(params, async(response) => {
            callback(response);//执行回调业务逻辑
        });
    };

    //发起网络代理API请求逻辑
    messageSrv.doTabSendMessage = async (tabId, params) => {
        try {
            const state = await new Promise((resolve, reject) => {
                chrome.tabs.sendMessage(tabId, params, (response) => {
                    // 必须检查 lastError，否则错误会被静默吞掉
                    if (chrome.runtime.lastError) {
                        reject(new Error(chrome.runtime.lastError.message));
                    } else {
                        resolve(response);
                    }
                });
            });
            return state;
        } catch (err) {
            utilSrv.Write(utilSrv.ERROR, "发送消息异常", err);
            return false;
        }
    };


    //发起网络代理API请求逻辑
    messageSrv.doSendMessage = async (params) => {
        try {
            const state = await new Promise((resolve, reject) => {
                chrome.runtime.sendMessage(params, (response) => {
                    // 必须检查 lastError，否则错误会被静默吞掉
                    if (chrome.runtime.lastError) {
                        reject(new Error(chrome.runtime.lastError.message));
                    } else {
                        resolve(response);
                    }
                });
            });
            return state;
        } catch (err) {
            utilSrv.Write(utilSrv.ERROR, "发送消息异常", err);
            return false;
        }
    };

    messageSrv.pagePostMessage = (data={type:"s", url:"", data:""}) => {
        const message = JSON.stringify(data);
        window.postMessage(message, '*');  // 将响应发送到 content script
    };

    messageSrv.pageMessageListener = () => {
        utilSrv.Write(utilSrv.INFO, '开启listener中转');
        window.addEventListener('message', function (e) {
             try {
                if (e.data && e.data.type === "FROM_EVAL5_TO_CONTENT") {
                    utilSrv.Write(utilSrv.INFO, 'listener中转', e.data);
                    if (e.data.isTab && e.data.isTab == 1) {
                        chrome.runtime.sendMessage({type:utilSrv.msgTabNotifyMsg,
                            data:e.data.payload, tabId:0});
                    } else {//系统通道的逻辑
                        chrome.runtime.sendMessage(e.data.payload);
                    }
                    return; //消息中转的逻辑
                }
                if (!messageSrv.cbNetworkHooks) {//不做监控底层其他消息的情况
                    return;
                }
                const result = (!e || !e.data)? null:e.data;
                utilSrv.Write(utilSrv.INFO, 'received:' , e);
                if (typeof(result) != 'string' || !result.startsWith('{') || !result.endsWith('}')) {
                    return;//非字符串跳过
                }
                const data = JSON.parse(result);
                if (data && data.type && (data.type == utilSrv.netReqXhr
                        || data.type == utilSrv.netReqFetch)) {
                    //抓取信息的回调逻辑
                    messageSrv.cbNetworkHooks(data.url, data.data);
                }
            } catch (err) {
                utilSrv.Write(utilSrv.INFO, 'listener:' , err);
            }
        });
    };
    return messageSrv;
})();

